package com.fuelflex.platform.reception.entity; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID; import com.fuelflex.platform.tank.entity.Tank; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; @Entity @Table(name="reception_tank_allocations") @Getter @Setter @NoArgsConstructor public class ReceptionTankAllocation { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="reception_item_id",nullable=false) private ReceptionItem receptionItem; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tank_id",nullable=false) private Tank tank; @Column(nullable=false,precision=19,scale=3) private BigDecimal quantity; @Column(nullable=false,updatable=false) private OffsetDateTime createdAt; @PrePersist void pre(){createdAt=OffsetDateTime.now();} }
